//game8.jp/dq1remake/735108","https://game8.jp/dq1remake/735384"]},{"name":"てつ的さそり","original":"てつのさそり","condition":"矮人洞窟_地下2层；来源按楼层列示；未独立确认白天夜晚或剧情刷新条件","drop":"药草","sources":["https://game8.jp/dq1remake/735108","https://game8.jp/dq1remake/735385"]},{"name":"アントベア","original":"アントベア","condition":"矮人洞窟_地下2层；来源按楼层列示；未独立确认白天夜晚或剧情刷新条件","drop":"药草","sources":["https://game8.jp/dq1remake/735108","https://game8.jp/dq1remake/735386"]},{"name":"食人箱","original":"ひとくいばこ","condition":"矮人洞窟_地下2层；来源按楼层列示；未独立确认白天夜晚或剧情刷新条件","drop":"祈祷戒指","sources":["https://game8.jp/dq1remake/735108","https://game8.jp/dq1remake/735431"]}],"npcs":[{"id":"dq1-735108-npc-1","name":"卧床矮人","original":"ベッドのドワーフ","role":"B3深处房间，需灯火的シロップ救治。","how":"","condition":"","detailImage":null,"sources":["https://game8.jp/dq1remake/732630","https://game8.jp/dq1remake/735108"]},{"id":"dq1-735108-npc-2","name":"蓝帽矮人","original":"青い帽子のドワーフ","role":"修复通往岩泣岛区域的桥。","how":"","condition":"梅尔基德事件推进后。","detailImage":null,"sources":["https://game8.jp/dq1remake/732630","https://game8.jp/dq1remake/735108"]}],"bosses":[],"tips":["先在利姆达尔补给并练至约16–17级，再向南进入矮人洞窟；附近敌人强，准备药草及适当盾盔。","洞窟楼梯较多，按地图逐支线清理。B1先拿冰盾、小徽章、奇迹卷轴；需最后钥匙的门本次先记下。","B2拿僵尸斩卷轴和小徽章；东侧宝箱是食人箱，当前打不过可先避开，击败掉祈祷戒指。","B3深处房间与卧床矮人对话。离开前从井下降B4，在泉水最深处拿泉水结晶；此后可用鲁拉传送直接到B3。","胜利后获得两份灯火的シロップ，送往矮人洞窟交给卧床矮人，推进救治事件。","回B3东北蓝门房间，拿ちから的指輪和盖亚铠甲。铠甲及冰盾可为即将到来的火焰战作准备。","回矮人洞窟找戴蓝帽的矮人，让他修复通往岩泣岛区域的桥。","墓地事件后矮人洞窟B3开放武器防具店，出售暴风雪之剑、智力头盔、带状铠甲等高级装备，可按预算补强。"],"sources":["https://game8.jp/dq1remake/735108","https://gamewith.jp/dq1-2/527446","https://gamewith.jp/dq1-2/479005"],"exits":[],"facilityImages":[],"position":[83.26388888888889,72.81955295138889]},{"id":"dq1-735084","name":"迷途森林","original":"迷いの森","translationStatus":"中文名称为工作暂译；原文用于对应地图","type":"dungeon","region":"dq1-region-10","description":"","access":"从徽章王城向东过桥。先跨地图至少两次再走东北触发驱雾，之后地图可用。","maps":[{"id":"dq1-735084-01","name":"迷途森林","original":"迷いの森","floorNames":["迷途森林①","迷途森林②"],"image":"reference/maps/dq1-735084-01.webp","sources":["https://game8.j